// Matched OTT v2 reference negamax/alpha-beta and UCT, C++17.
#include <algorithm>
#include <chrono>
#include <cmath>
#include <iostream>
#include <memory>
#include <random>
#include <string>
#include <vector>
#include "json.hpp"
using json=nlohmann::json;using Board=std::vector<int>;using Move=std::pair<int,int>;
using Clock=std::chrono::steady_clock;
constexpr int WIN=1000000,THINK_MS=100,MAX_DEPTH=8;
const std::string MODE="alphabeta"; // alphabeta / defensive / random / mcts
int rows=9,cols=9,bases[2]={72,8},eliminate=1;bool capture=true;
std::vector<std::vector<int>> neighbors;std::mt19937 rng(20261015);
long long nodes;Clock::time_point deadline;
int owner(int p){return (p-1)/3;}int kind(int p){return (p-1)%3;}
int square(std::string s){return (rows-std::stoi(s.substr(1)))*cols+s[0]-'a';}
std::string square(int s){return std::string(1,char(97+s%cols))+std::to_string(rows-s/cols);}
int distance(int a,int b){return std::max(abs(a/cols-b/cols),abs(a%cols-b%cols));}
std::vector<Move> moves(const Board& b,int side){std::vector<Move> out;for(int s=0;s<(int)b.size();s++)if(b[s]&&owner(b[s])==side)for(int t:neighbors[s])if(!b[t]||(owner(b[t])!=side&&(kind(b[s])+2)%3==kind(b[t])))out.emplace_back(s,t);return out;}
std::pair<Board,int> play(const Board& b,int side,Move m){Board out=b;out[m.second]=out[m.first];out[m.first]=0;bool kinds[3]={};for(int p:out)if(p&&owner(p)!=side)kinds[kind(p)]=true;int absent=0;for(bool k:kinds)absent+=!k;return {out,((capture&&m.second==bases[1-side])||absent>=eliminate)?side:-1};}
int evaluate(const Board& b,int side){int scores[2]={},nearest[2]={std::max(rows,cols),std::max(rows,cols)};for(int s=0;s<(int)b.size();s++)if(b[s]){int who=owner(b[s]),d=distance(s,bases[1-who]);nearest[who]=std::min(nearest[who],d);scores[who]+=100+4*(std::max(rows,cols)-d);}for(int who=0;who<2;who++)scores[who]+=25*(std::max(rows,cols)-nearest[who]);return scores[side]-scores[1-side];}
std::vector<Move> ordered(const Board& b,int side,std::vector<Move> legal){auto score=[&](Move m){return 10000*(capture&&m.second==bases[1-side])+100*bool(b[m.second])+distance(m.first,bases[1-side])-distance(m.second,bases[1-side]);};std::stable_sort(legal.begin(),legal.end(),[&](Move a,Move c){return score(a)>score(c);});return legal;}
struct Expired{};
int negamax(const Board& b,int side,int depth,int alpha,int beta){if(++nodes%16==0&&Clock::now()>=deadline)throw Expired{};auto legal=moves(b,side);if(legal.empty())return -WIN;if(!depth)return evaluate(b,side);int best=-2*WIN;for(auto m:ordered(b,side,legal)){auto [child,winner]=play(b,side,m);int value=winner==side?WIN:-negamax(child,1-side,depth-1,-beta,-alpha);best=std::max(best,value);alpha=std::max(alpha,value);if(alpha>=beta)break;}return best;}
struct Node{Board b;int side,winner;Move move;std::vector<Move> untried;std::vector<std::unique_ptr<Node>> children;int n=0;double v=0;Node(Board a,int s,int w=-1):b(std::move(a)),side(s),winner(w),untried(w<0?moves(b,s):std::vector<Move>{}){}};
Move mcts(const Board& b,int side,const std::vector<Move>& legal){Node root(b,side);while(Clock::now()<deadline){Node* cur=&root;std::vector<Node*> path{cur};while(cur->untried.empty()&&!cur->children.empty()){double best=-1e99;Node* chosen=nullptr;for(auto& child:cur->children){double u=(cur->side==side?1:-1)*child->v/child->n+std::sqrt(2*std::log(std::max(1,cur->n))/child->n);if(u>best){best=u;chosen=child.get();}}cur=chosen;path.push_back(cur);}if(!cur->untried.empty()){Move m=cur->untried.back();cur->untried.pop_back();auto [board,w]=play(cur->b,cur->side,m);cur->children.push_back(std::make_unique<Node>(board,1-cur->side,w));cur=cur->children.back().get();cur->move=m;path.push_back(cur);}Board board=cur->b;int s=cur->side,w=cur->winner;for(int i=0;i<16&&w<0;i++){auto ms=moves(board,s);if(ms.empty()){w=1-s;break;}auto next=play(board,s,ms[rng()%ms.size()]);board=next.first;w=next.second;s=1-s;nodes++;}double reward=w>=0?(w==side?1.:-1.):std::tanh(evaluate(board,side)/500.);for(auto node:path){node->n++;node->v+=reward;}}if(root.children.empty())return legal[0];return (*std::max_element(root.children.begin(),root.children.end(),[](auto& a,auto& b){return a->n<b->n;}))->move;}
std::pair<Move,json> choose(const Board& b,int side,int ms=THINK_MS){auto started=Clock::now();deadline=started+std::chrono::milliseconds(ms);nodes=0;auto legal=ordered(b,side,moves(b,side));Move best=legal[0];int completed=0;if(MODE=="random")best=legal[rng()%legal.size()];else if(MODE=="mcts")best=mcts(b,side,legal);else for(int depth=1;depth<=(MODE=="defensive"?1:MAX_DEPTH);depth++){Move candidate=best;int alpha=-2*WIN;try{for(auto move:legal){auto [child,winner]=play(b,side,move);int value=winner==side?WIN:-negamax(child,1-side,depth-1,-2*WIN,-alpha);if(MODE=="defensive")for(auto enemy:moves(child,1-side))if(enemy.second==move.second)value-=30;if(value>alpha){alpha=value;candidate=move;}}best=candidate;completed=depth;if(Clock::now()>=deadline||alpha>=WIN)break;}catch(Expired&){break;}}return {best,{{"nodes",nodes},{"depth",completed},{"search_ms",std::chrono::duration<double,std::milli>(Clock::now()-started).count()}}};}
std::pair<Board,int> configure(const json& p){auto state=p.at("state");rows=state.at("board").size();cols=state.at("board").at(0).size();auto rules=state.value("basic_rules",json::object());auto base=p.at("bases");bases[0]=square(base.at("red").get<std::string>());bases[1]=square(base.at("blue").get<std::string>());eliminate=rules.value("eliminate_types",1);capture=rules.value("base_capture",true);neighbors.assign(rows*cols,{});Board board(rows*cols);for(int i=0;i<rows*cols;i++){for(int dr=-1;dr<=1;dr++)for(int dc=-1;dc<=1;dc++){int nr=i/cols+dr,nc=i%cols+dc;if((dr||dc)&&nr>=0&&nr<rows&&nc>=0&&nc<cols)neighbors[i].push_back(nr*cols+nc);}auto piece=state.at("board").at(i/cols).at(i%cols);if(!piece.is_null()){std::string k=piece.at("kind");board[i]=1+(piece.at("side")=="red"?0:3)+(k=="rock"?0:k=="paper"?1:2);}}return {board,state.at("to_move")=="red"?0:1};}
int main(){std::ios::sync_with_stdio(false);std::cin.tie(nullptr);std::string line;while(std::getline(std::cin,line)){try{auto m=json::parse(line);json out={{"protocol_version",2},{"match_id",m.at("match_id")}};if(m.at("type")=="init")out["type"]="ready";else{auto [board,side]=configure(m.at("payload"));json action={{"resign",true}};if(!moves(board,side).empty()){auto [move,stats]=choose(board,side,std::min(THINK_MS,std::max(0,m.at("timing").at("budget_ms").get<int>()/2-5)));action={{"from",square(move.first)},{"to",square(move.second)}};std::cerr<<stats.dump()<<'\n'<<std::flush;}out.update({{"type","action"},{"turn_id",m.at("turn_id")},{"state_version",m.at("state_version")},{"payload",action}});}std::cout<<out.dump()<<'\n'<<std::flush;}catch(const std::exception& e){std::cerr<<e.what();return 1;}}}
